    '4dd68bff-c571-4913-8e5b-c08a364a030e', 'LS6_KNTT_B04', '8c73cfde-a6a6-4341-938b-9ee8a3b2e16c', '6', 'KNTT', 'LS', 
    4, 'NGUỒN GỐC LOÀI NGƯỜI', 
    '[
"Mô tả được quá trình tiến hoá từ Vượn người thành người trên Trái Đất.",
"Xác định được dấu tích của Người tối cổ ở Đông Nam Á và Việt Nam."
]', '[{"id": "55cbc813-a10a-41b3-8d71-53b0ff29db6c", "url": "https://res.cloudinary.com/myimagename/image/upload/v1791969542/H%C3%ACnh_4.1._C%C3%A1c_d%E1%BA%A1ng_ng%C6%B0%E1%BB%9Di_trong_qu%C3%A1_tr%C3%ACnh_ti%E1%BA%BFn_ho%C3%A1_am6lng.png", "caption": "Hình 4.1. Các dạng người trong quá trình tiến hoá"}, {"id": "b54ddcff-a7b2-4a27-9748-0674d4081c5e", "url": "https://res.cloudinary.com/myimagename/image/upload/v1791969633/H%C3%ACnh_4.2._L%C6%B0%E1%BB%A3c_%C4%91%E1%BB%93_d%E1%BA%A5u_t%C3%ADch_c%E1%BB%A7a_qu%C3%A1_tr%C3%ACnh_chuy%E1%BB%83n_bi%E1%BA%BFn_t%E1%BB%AB_V%C6%B0%E1%BB%A3n_ng%C6%B0%E1%BB%9Di_th%C3%A0nh_ng%C6%B0%E1%BB%9Di_%E1%BB%9F_%C4%90%C3%B4ng_Nam_%C3%81_sjehy9.png", "caption": "Hình 4.2. Lược đồ dấu tích của quá trình chuyển biến từ Vượn người thành người ở Đông Nam Á"}, {"id": "e72a6bba-10ce-45f8-ba93-d7bb9479affe", "url": "https://res.cloudinary.com/myimagename/image/upload/v1791969694/H%C3%ACnh_4.3._C%C3%B4ng_c%E1%BB%A5_%C4%91%C3%A1_N%C3%BAi_%C4%90%E1%BB%8D_Thanh_Ho%C3%A1_gx3fmq.png", "caption": "Hình 4.3. Công cụ đá Núi Đọ Thanh Hoá"}, {"id": "f24db78a-b528-46c5-9670-1dfb35b78199", "url": "https://res.cloudinary.com/myimagename/image/upload/v1791969694/H%C3%ACnh_4.4._R%C4%83ng_ho%C3%A1_th%E1%BA%A1ch_c%E1%BB%A7a_Ng%C6%B0%E1%BB%9Di_t%E1%BB%91i_c%E1%BB%95_%C4%91%C6%B0%E1%BB%A3c_t%C3%ACm_th%E1%BA%A5y_%E1%BB%9F_hang_Th%E1%BA%A9m_Khuy%C3%AAn_L%E1%BA%A1ng_S%C6%A1n_vkbk7z.png", "caption": "Hình 4.4. Răng hoá thạch của Người tối cổ được tìm thấy ở hang Thẩm Khuyên Lạng Sơn"}, {"id": "3e8c54ee-0044-4c30-a85f-40ae6a2b52c5", "url": "https://res.cloudinary.com/myimagename/image/upload/v1791969695/H%C3%ACnh_4.5._R%C3%ACu_tay_t%C3%ACm_th%E1%BA%A5y_%E1%BB%9F_di_ch%E1%BB%89_An_Kh%C3%AA_Gia_Lai_qjrthy.png", "caption": "Hình 4.5. Rìu tay tìm thấy ở di chỉ An Khê Gia Lai"}]', 
    1, 'published', 'clean'
);
INSERT INTO lesson_content (
    lesson_id, raw_content
) VALUES (
    '4dd68bff-c571-4913-8e5b-c08a364a030e', '# Bài 4: NGUỒN GỐC LOÀI NGƯỜI

**Học xong bài này, em sẽ:**
- Mô tả được quá trình tiến hoá từ Vượn người thành người trên Trái Đất.
- Xác định được dấu tích của Người tối cổ ở Đông Nam Á và Việt Nam.

**Câu hỏi khởi động:** Người châu Phi, châu Á và châu Âu có màu da như thế nào? Liệu họ có cùng chung một nguồn gốc hay không? Nếu có thì từ đâu mà ra?

> **Em có biết?**
> Những phát hiện gần đây ở Đông Phi đã dẫn tới quan điểm cho rằng nơi đây là một trong những “cái nôi” của loài người.
> Người tối cổ thường xuyên đi, đứng bằng hai chân, hai chi trước trở thành hai tay khéo léo, thể tích sọ não lớn hơn và đã hình thành trung tâm phát tiếng nói trong não.

## 1. Quá trình tiến hoá từ Vượn người thành người

Quá trình tiến hoá từ Vượn người thành người đã diễn ra cách đây hàng triệu năm. Ở chặng đầu của quá trình đó, cách ngày nay khoảng 5 – 6 triệu năm, đã có một loài Vượn người sinh sống. Từ loài Vượn người, một nhánh đã phát triển lên thành Người tối cổ. Dạng người này xuất hiện khoảng 4 triệu năm trước, đến khoảng 15 vạn năm trước thì biến đổi thành Người tinh khôn.

[ẢNH: Hình 4.1. Các dạng người trong quá trình tiến hoá]

**Câu hỏi:**
1. Dựa vào hình trên và trục thời gian (tr.16) em hãy cho biết quá trình tiến hoá từ Vượn người thành người đã trải qua các giai đoạn nào? Cho biết niên đại tương ứng của các giai đoạn đó.

## 2. Những dấu tích của quá trình chuyển biến từ Vượn người thành người ở Đông Nam Á và Việt Nam

Tại khu vực Đông Nam Á đã diễn ra quá trình tiến hóa từ Vượn người thành người từ rất sớm. Dấu tích của Người tối cổ đã được tìm thấy ở khắp Đông Nam Á và cả Việt Nam. Đó là những di cốt hóa thạch và công cụ đá do con người chế tạo ra.

[ẢNH: Hình 4.2. Lược đồ dấu tích của quá trình chuyển biến từ Vượn người thành người ở Đông Nam Á]

Di cốt của loài Vượn người sống cách ngày nay khoảng 5 triệu năm đã được tìm thấy ở Mi-an-ma và In-đô-nê-xi-a. Đặc biệt, hóa thạch phát hiện trên đảo Gia-va (In-đô-nê-xi-a) có niên đại khoảng 2 triệu năm trước là dấu vết xưa nhất của Người tối cổ ở Đông Nam Á. Di cốt, mảnh di cốt và những công cụ đá của Người tối cổ còn được tìm thấy ở Thái Lan, Phi-líp-pin, Ma-lai-xi-a. Chiếc sọ Người tinh khôn tìm thấy ở hang Ni-a (Ma-lai-xi-a) có niên đại cách ngày nay khoảng 4 vạn năm.

Ở Việt Nam cũng đã phát hiện răng của Người tối cổ ở Thẩm Khuyên, Thẩm Hai (Lạng Sơn),... Những công cụ đá được ghè đẽo thô sơ của Người tối cổ cũng đã có mặt ở An Khê (Gia Lai), Núi Đọ (Thanh Hóa), Xuân Lộc (Đồng Nai), An Lộc (Bình Phước),...

[ẢNH: Hình 4.3. Công cụ đá Núi Đọ (Thanh Hóa)]

[ẢNH: Hình 4.4. Răng hóa thạch của Người tối cổ được tìm thấy ở hang Thẩm Khuyên (Lạng Sơn)]

[ẢNH: Hình 4.5. Rìu tay tìm thấy ở di chỉ An Khê (Gia Lai)]

> **Em có biết?**
> Tại di chỉ An Khê (thị xã An Khê, tỉnh Gia Lai), người ta đã phát hiện được trên 3 000 hiện vật đá (gồm rìu tay, công cụ ghè đẽo thô sơ,...) có niên đại cách ngày nay 80 vạn năm. Đây là dấu tích cổ xưa nhất chứng tỏ sự xuất hiện sớm của người nguyên thuỷ trên đất nước Việt Nam.

**Câu hỏi:**
1. Hãy xác định những dấu tích của Người tối cổ tìm được ở Đông Nam Á và Việt Nam trên lược đồ (hình 4.2, tr.18). Những dấu tích đó chứng tỏ điều gì?

## Luyện tập – Vận dụng

**Luyện tập:**
1. Từ những thông tin và hình ảnh trong bài học, hãy cho biết những bằng chứng nào chứng tỏ ở khu vực Đông Nam Á và Việt Nam diễn ra quá trình tiến hoá từ Vượn người thành người?
2. Quan sát hình 4.1 (tr.17), em thấy Vượn người, Người tinh khôn và Người tối cổ có điểm gì khác nhau?

**Vận dụng:**
1. Làm việc theo nhóm: Hãy sưu tầm tư liệu (chữ viết, hình ảnh) và giới thiệu quá trình phát triển của người nguyên thuỷ trên thế giới hoặc ở Việt Nam.
'
);

