imagename/image/upload/v1791968136/H%C3%ACnh_10.6._T%C6%B0%E1%BB%A3ng_P%C3%AA-ri-cl%C3%A9t_495_429_TCN_Ch%E1%BA%A5p_ch%C3%ADnh_quan_trong_th%E1%BB%9Di_%C4%91%E1%BA%A1i_ho%C3%A0ng_kim_c%E1%BB%A7a_A-ten_veoyll.png", "caption": "Hình 10.6. Tượng Pê-ri-clét 495 429 TCN Chấp chính quan trong thời đại hoàng kim của A-ten"}, {"id": "0b1fc1c7-7890-41af-b5a4-9e0307fd531c", "url": "https://res.cloudinary.com/myimagename/image/upload/v1791968137/H%C3%ACnh_10.7._T%C6%B0%E1%BB%A3ng_%C3%93c-ta-vi-%C3%BAt_63_TCN_14_ng%C6%B0%E1%BB%9Di_m%E1%BB%9F_%C4%91%E1%BA%A7u_th%E1%BB%9Di_k%C3%AC_%C4%91%E1%BA%BF_ch%E1%BA%BF_La_M%C3%A3_anvixx.png", "caption": "Hình 10.7. Tượng Óc-ta-vi-út 63 TCN 14 người mở đầu thời kì đế chế La Mã"}, {"id": "10725f14-fd87-4850-bbb1-0efde5327b92", "url": "https://res.cloudinary.com/myimagename/image/upload/v1791968138/H%C3%ACnh_10.8._S%C6%A1_%C4%91%E1%BB%93_t%E1%BB%95_ch%E1%BB%A9c_Nh%C3%A0_n%C6%B0%E1%BB%9Bc_%C4%91%E1%BA%BF_ch%E1%BA%BF_%E1%BB%9F_La_M%C3%A3_vmaa7z.png", "caption": "Hình 10.8. Sơ đồ tổ chức Nhà nước đế chế ở La Mã"}, {"id": "97960582-d591-4ba5-b71b-bd6a037f0810", "url": "https://res.cloudinary.com/myimagename/image/upload/v1791968140/H%C3%ACnh_10.9._B%E1%BA%A3ng_ch%E1%BB%AF_c%E1%BB%95_Hy_L%E1%BA%A1p_v%C3%A0_La-tinh_ivrore.png", "caption": "Hình 10.9. Bảng chữ cổ Hy Lạp và La-tinh"}, {"id": "080a2cf1-832e-417a-9a45-0e5710eb6f00", "url": "https://res.cloudinary.com/myimagename/image/upload/v1791968129/H%C3%ACnh_10.10._B%E1%BA%A3ng_ch%E1%BB%AF_s%E1%BB%91_La_M%C3%A3_t0wvg8.png", "caption": "Hình 10.10. Bảng chữ số La Mã"}, {"id": "cabdb656-5caa-4b74-a73c-5dfde7ff2aa3", "url": "https://res.cloudinary.com/myimagename/image/upload/v1791968129/H%C3%ACnh_10.11._T%C6%B0%E1%BB%A3ng_L%E1%BB%B1c_s%C4%A9_n%C3%A9m_%C4%91%C4%A9a_b%E1%BA%B1ng_%C4%91%C3%A1_c%E1%BA%A9m_th%E1%BA%A1ch_tr%E1%BA%AFng_gxjrgk.png", "caption": "Hình 10.11. Tượng Lực sĩ ném đĩa bằng đá cẩm thạch trắng"}, {"id": "649e71f2-eae7-4f36-a870-bda7b8f4dd32", "url": "https://res.cloudinary.com/myimagename/image/upload/v1791968130/H%C3%ACnh_10.12._%C4%90%E1%BA%A5u_tr%C6%B0%E1%BB%9Dng_C%C3%B4-li-d%C3%AA_La_M%C3%A3_lctdoq.png", "caption": "Hình 10.12. Đấu trường Cô-li-dê La Mã"}, {"id": "fa9cb35a-dbb3-48f5-86ed-497143a65242", "url": "https://res.cloudinary.com/myimagename/image/upload/v1791968131/H%C3%ACnh_10.13._Tr%E1%BB%A5c_th%E1%BB%9Di_gian_Hy_L%E1%BA%A1p_v%C3%A0_La_M%C3%A3_c%E1%BB%95_%C4%91%E1%BA%A1i_sy6e3e.png", "caption": "Hình 10.13. Trục thời gian Hy Lạp và La Mã cổ đại"}]', 
