]', '[{"id": "1da15498-af10-4c4a-abf3-eaa5f1fa49df", "url": "https://res.cloudinary.com/myimagename/image/upload/v1791968963/H%C3%ACnh_17.1._S%E1%BB%B1_t%C3%ADch_tr%E1%BA%A7u_cau_l%C3%AD_gi%E1%BA%A3i_t%E1%BB%A5c_%C4%83n_tr%E1%BA%A7u_c%E1%BB%A7a_ng%C6%B0%E1%BB%9Di_Vi%E1%BB%87t_tranh_minh_ho%E1%BA%A1_yebbjd.png", "caption": "Hình 17.1. Sự tích trầu cau lí giải tục ăn trầu của người Việt tranh minh hoạ"}, {"id": "d64b6bf9-197d-4975-9830-52a3fb7e4a95", "url": "https://res.cloudinary.com/myimagename/image/upload/v1791968963/H%C3%ACnh_17.2._S%C6%A1_%C4%91%E1%BB%93_ti%E1%BA%BFp_thu_c%C3%B3_ch%E1%BB%8Dn_l%E1%BB%8Dc_v%C4%83n_ho%C3%A1_Trung_Hoa_ozf8gg.png", "caption": "Hình 17.2. Sơ đồ tiếp thu có chọn lọc văn hoá Trung Hoa"}]', 
