cd8a-7ecc-4d2c-9ebb-8e95a8f083d6", "url": "https://res.cloudinary.com/myimagename/image/upload/v1791968973/H%C3%ACnh_18.6._M%C3%B4_ph%E1%BB%8Fng_tr%E1%BA%ADn_%C4%91%E1%BB%8Ba_c%E1%BB%8Dc_tr%C3%AAn_s%C3%B4ng_B%E1%BA%A1ch_%C4%90%E1%BA%B1ng_tranh_minh_ho%E1%BA%A1_o3zajd.png", "caption": "Hình 18.6. Mô phỏng trận địa cọc trên sông Bạch Đằng tranh minh hoạ"}, {"id": "c43364d2-c40a-4ac2-bf6c-011fb2e488e3", "url": "https://res.cloudinary.com/myimagename/image/upload/v1791968974/H%C3%ACnh_18.7._L%C6%B0%E1%BB%A3c_%C4%91%E1%BB%93_tr%E1%BA%ADn_B%E1%BA%A1ch_%C4%90%E1%BA%B1ng_n%C4%83m_938_qfg4em.png", "caption": "Hình 18.7. Lược đồ trận Bạch Đằng năm 938"}]', 
