]', '[{"id": "535195e3-f5bd-49ee-9cf2-d55ebea8e569", "url": "https://res.cloudinary.com/myimagename/image/upload/v1791956269/H%C3%ACnh_1.1_aeq3rk.png", "caption": "Hình 1.1. Nhà máy Đni-ép được khởi công xây dựng năm 1927"}, {"id": "b31efc69-41a2-4b9b-a544-a5d69f3377b7", "url": "https://res.cloudinary.com/myimagename/image/upload/v1791956269/H%C3%ACnh_1.2_noxpjo.png", "caption": "Hình 1.2. Lược đồ nước Nga Xô viết chống thù trong, giặc ngoài (1918 – 1920)"}, {"id": "7ffb4de8-402d-4636-9bec-fcb586251e6f", "url": "https://res.cloudinary.com/myimagename/image/upload/v1791956270/H%C3%ACnh_1.3_i6db8a.png", "caption": "Hình 1.3. Thành phố Mát-xcơ-va trong những năm 20 của thế kỉ XX"}, {"id": "0063d8e8-d71d-4f24-86a2-bba96665cc80", "url": "https://res.cloudinary.com/myimagename/image/upload/v1791956270/H%C3%ACnh_1.4._V.I_ava4i5.png", "caption": "Hình 1.4. V.I. Lê-nin – người sáng lập Nhà nước Xô viết"}]', 
