    2, 'CHÂU ÂU VÀ NƯỚC MỸ TỪ NĂM 1918 ĐẾN NĂM 1945', 
    '[
"Trình bày được những nét chính về: phong trào cách mạng và sự thành lập Quốc tế Cộng sản; đại suy thoái kinh tế 1929 – 1933; sự hình thành chủ nghĩa phát xít ở châu Âu.",
"Nhận biết được tình hình chính trị và sự phát triển kinh tế nước Mỹ giữa hai cuộc chiến tranh thế giới."
]', '[{"id": "b431a3a7-914f-48c4-b517-70720967f1ce", "url": "https://res.cloudinary.com/myimagename/image/upload/v1791956362/H%C3%ACnh_2.1_trqum3.png", "caption": "Hình 2.1. Những chiếc xe hơi được rao bán với giá 100 USD trong đại suy thoái kinh tế (Mỹ, 1929)"}, {"id": "3da39846-7322-4636-a9eb-908a0c51bcc1", "url": "https://res.cloudinary.com/myimagename/image/upload/v1791956363/H%C3%ACnh_2.2_ed4nmh.png", "caption": "Hình 2.2. Tổng thống Hin-đen-bua trao quyền thủ tướng cho Hít-le (Đức, 1933)"}, {"id": "2e67a446-a941-4c85-a5f5-35983b4a5652", "url": "https://res.cloudinary.com/myimagename/image/upload/v1791956363/H%C3%ACnh_2.3_kpiogn.png", "caption": "Hình 2.3. Nhân dân tập trung trước toà nhà Rây-xtác (Đức) trong buổi tuyên bố thành lập chính phủ mới (1918)"}, {"id": "dabb4add-a667-4079-8693-a8c46a0afb95", "url": "https://res.cloudinary.com/myimagename/image/upload/v1791956364/H%C3%ACnh_2.4_s2vrm5.png", "caption": "Hình 2.4. Dòng người thất nghiệp ở Hà Lan trong đại suy thoái kinh tế"}, {"id": "4d274092-0edf-4c97-b512-2af511423bd7", "url": "https://res.cloudinary.com/myimagename/image/upload/v1791956364/H%C3%ACnh_2.5._T%E1%BB%95ng_th%E1%BB%91ng_Ph_ncrulw.png", "caption": "Hình 2.5. Tổng thống Ph. Ru-dơ-ven tuyên bố nhậm chức (1933)"}, {"id": "0e4be9b2-6e22-4e49-8bf1-935782b85f5e", "url": "https://res.cloudinary.com/myimagename/image/upload/v1791956364/H%C3%ACnh_2.6_o0bbmq.png", "caption": "Hình 2.6. Cuộc mít tinh của những người thất nghiệp ở Mỹ (1931)"}, {"id": "1eb9b83a-76cf-488b-8686-8a6beecb44a5", "url": "https://res.cloudinary.com/myimagename/image/upload/v1791956365/H%C3%ACnh_2.7_cs7rer.png", "caption": "Hình 2.7. Bức tranh đương thời mô tả Chính sách mới của Mỹ (người khổng lồ tượng trưng cho Nhà nước)"}]', 
